import * as React from "react";
import { CommonProps } from "../../utility/commonProps";
export interface DataTableBodyProps extends React.ComponentPropsWithoutRef<"tbody">, CommonProps {
    /**
     * The content for the data table body.
     */
    children: React.ReactNode;
}
/**
 * Data Table Body is the container for Data Table Rows.
 *
 * - {@link https://livingdesign.walmart.com/components/data-table/ Guidelines}
 * - {@link https://livingdesign.walmart.com/components/data-table/react/ React documentation}
 *
 * ### Content
 *
 * Data Table Body accepts content (Data Table Rows) through the `children` prop.
 *
 * ```tsx
 * <DataTable>
 *   <DataTableBody>
 *     <DataTableRow>
 *       <DataTableCell>James</DataTableCell>
 *       <DataTableCell>Kirk</DataTableCell>
 *     </DataTableRow>
 *   </DataTableBody>
 * </DataTable>
 * ```
 */
export declare const DataTableBody: React.FunctionComponent<DataTableBodyProps>;
